def order_book_imbalance(bid_qty, ask_qty):
    return (bid_qty - ask_qty) / (bid_qty + ask_qty)

def microprice(bid_price, bid_qty, ask_price, ask_qty):
    total = bid_qty + ask_qty
    return bid_price * (ask_qty / total) + ask_price * (bid_qty / total)

snapshots = [
    ("A", 840.00, 3000, 840.05, 1000),
    ("B", 840.00, 800, 840.05, 2400),
]

for label, bp, bq, ap, aq in snapshots:
    obi = order_book_imbalance(bq, aq)
    mid = (bp + ap) / 2
    micro = microprice(bp, bq, ap, aq)
    print(f"{label}: OBI={obi:.2f}, midpoint={mid:.4f}, microprice={micro:.4f}")

# A: OBI=0.50, midpoint=840.0250, microprice=840.0375
# B: OBI=-0.50, midpoint=840.0250, microprice=840.0125
